# Build prediction for the task using the verified rule
bg_color = 1

def get_horizontal_segments_per_row(grid, bg):
    """Extract contiguous horizontal segments of non-background cells"""
    segments = []
    for r in range(len(grid)):
        c = 0
        while c < len(grid[r]):
            if grid[r][c] != bg:
                color = grid[r][c]
                start = c
                while c < len(grid[r]) and grid[r][c] == color:
                    c += 1
                end = c - 1
                segments.append({
                    'row': r,
                    'start': start,
                    'end': end, 
                    'color': color,
                    'cells': list(range(start, end+1))
                })
            else:
                c += 1
    return segments

def simulate_shift_for_segment(segment, grid, bg):
    """Simulate shift for one segment, considering blocking"""
    height = len(grid)

    can_shift_all = True

    # Check if ANY cell would be blocked
    for c in segment['cells']:
        r = segment['row']

        # Blocked by right neighbor (non-bg)
        if c + 1 < len(grid[r]):
            right_val = grid[r][c+1]
            if right_val != bg:
                can_shift_all = False
                break

        # Same color below (anywhere down) - will block movement
        for dr in range(1, height - r):
            if r + dr < height and grid[r+dr][c] == segment['color']:
                can_shift_all = False
                break

    if not can_shift_all:
        return segment  # No shift

    return {**segment, 'shifted_cells': set(c+1 for c in segment['cells'])}

# Load task input
task_input = grid
height = len(task_input)
width = len(task_input[0])

# Create output grid initialized with background
output = [[bg_color for _ in range(width)] for _ in range(height)]

# Get all segments from input
segments = get_horizontal_segments_per_row(task_input, bg_color)
print(f"Found {len(segments)} segments in task input")

# Simulate each segment
all_shifted = []
for seg in segments:
    shifted_seg = simulate_shift_for_segment(seg, task_input, bg_color)
    all_shifted.append(shifted_seg)
    print(f"\nSegment at ({seg['row']},{seg['start']}-{seg['end']}), color={seg['color']}")
    print(f"  Can shift: {seg['cells']} → {shifted_seg.get('shifted_cells', seg['cells'])}")

# Place shifted cells in output
for seg in all_shifted:
    if 'shifted_cells' in seg:
        for c in seg['shifted_cells']:
            new_c = c
            if new_c < width:
                output[seg['row']][new_c] = seg['color']
            else:
                # Cell moves off-grid (unlikely but handle it)
                pass
    else:
        # Didn't shift, keep in place
        for c in seg['cells']:
            output[seg['row']][c] = seg['color']

print("\n=== Predicted Output ===")
for r in range(height):
    row_str = " ".join(f"{cell}" for cell in output[r])
    print(row_str)

