    """Find all positions of given color connected via 4-way connectivity"""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    queue = deque([start_pos])

    while queue:
        r, c = queue.popleft()
        if (r, c) in visited:
            continue
        visited.add((r, c))

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color:
